import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, you are asked to analyze a weighted symmetry condition depending on two fixed integers {p} and {q}. For each positive integer n, consider all nondecreasing sequences of positive reals a_1 \\leq a_2 \\leq \\cdots \\leq a_n that satisfy the weighted equality \\(\\sum_{k=1}^n k^{\\,{q}}\\,a_k = \\sum_{k=1}^n \\frac{k^{\\,{q}}}{a_k}\\). Determine all positive integers n for which, for every such sequence, the inequality \\(\\prod_{k=1}^n a_k^{\\,k^{\\,{p}}} \\geq 1\\) holds. After you determine the full set of all such n, output it in the required format: \n### The final answer is: $\\boxed{\\{n_1, n_2, \\dots, n_t\\}}$'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an exponent p >= 2 so that the family is nontrivial and the answer set is finite and sizable
p = rng.choice([2, 3, 4])
# Choose a weight exponent q >= 1; it does not affect the correctness threshold but makes the instance richer
q = rng.randint(1, min(3, p))
return {'p': p, 'q': q}

    def verifier(assign):
# Validate inputs
if 'p' not in assign or 'q' not in assign:
    return (False, None)  # missing params
p = assign['p']
q = assign['q']
if not (isinstance(p, int) and isinstance(q, int)):
    return (False, None)  # wrong types
if p < 2 or q < 1:
    return (False, None)  # out of supported domain to ensure nontriviality and monotonic growth needed for proof

# Classification principle used (proved in notes):
# Let e_k = k^p and consider n >= 1. If S_prev(n) := sum_{k=1}^{n-1} e_k <= e_n, then for every nondecreasing sequence
# (a_k) > 0 with \sum k^q a_k = \sum k^q / a_k, we have prod a_k^{e_k} >= 1.
# If S_prev(n) > e_n, the property fails (constructive counterexample by pushing a_1=...=a_{n-1} -> 0 and compensating a_n -> +inf).

# Compute all n satisfying S_prev(n) <= e_n. For p >= 2, this set is an initial segment {1,2,...,N} for some finite N,
# because S_prev(n)/e_n grows beyond 1 eventually.

good_ns = []
# We'll scan a safe range and stop when it definitely fails and keeps failing; for p>=2 this happens quickly.
max_scan = 200  # safe cap
s_prev = 0
for n in range(1, max_scan + 1):
    e_n = n ** p
    if s_prev <= e_n:
        good_ns.append(n)
    else:
        # Once s_prev > e_n for some n, it will remain so for all larger n for p>=2; we can safely stop.
        break
    s_prev += e_n  # prepare for next n: add current e_n to S_prev(n+1)

# Form the final answer string
if len(good_ns) == 0:
    # Should never happen for p>=2 (n=1 always works)
    return (False, None)

ans_str = '### The final answer is: $\\boxed{\\{' + ', '.join(str(x) for x in good_ns) + '\\}}$'
return (True, ans_str)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

